    // Index lifecycle
    fun createIndex(indexName: String, metadata: IndexMetadata): Boolean
    fun deleteIndex(indexName: String): Boolean
    fun reindex(sourceIndex: String, targetIndex: String): Long

    // Template management
    fun listTemplates(): List<IndexTemplate>
