## 4. Infrastructure Implementations

### 4.1 IndexRepositoryImpl.kt
```kotlin
package com.cowave.search.infrastructure

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch.indices.*
import com.cowave.search.domain.index.IndexMetadata
import com.cowave.search.domain.index.IndexSettings
import com.cowave.search.domain.index.IndexTemplate
import com.cowave.search.service.IndexRepository
import org.springframework.stereotype.Repository

@Repository
class IndexRepositoryImpl(
    private val esClient: ElasticsearchClient,
) : IndexRepository {

    override fun listIndices(pattern: String): List<String> {
        val response = esClient.cat().indices { it.index(pattern) }
        return response.valueBody().mapNotNull { it.index() }
    }

    override fun getIndexMetadata(indexName: String): IndexMetadata {
        val indexResponse = esClient.indices().get { it.index(indexName) }
        val indexData = indexResponse[indexName] ?: throw IllegalArgumentException("Index not found: $indexName")

        val statsResponse = esClient.indices().stats { it.index(indexName) }
        val stats = statsResponse.indices()[indexName]

        return IndexMetadata(
            indexName = indexName,
            settings = indexData.settings()?.index()?.toMap() ?: emptyMap(),
            mappings = indexData.mappings()?.toMap() ?: emptyMap(),
            aliases = indexData.aliases().mapValues { emptyMap<String, Any>() },
            documentCount = stats?.primaries()?.docs()?.count() ?: 0,
            sizeInBytes = stats?.primaries()?.store()?.sizeInBytes() ?: 0,
        )
    }

    override fun exportAllDocuments(indexName: String, batchSize: Int): Sequence<Map<String, Any>> = sequence {
        var searchAfter: List<FieldValue>? = null

        do {
            val response = esClient.search({ s ->
                s.index(indexName)
                    .size(batchSize)
                    .sort { so -> so.field { f -> f.field("_doc").order(SortOrder.Asc) } }
                    .apply { searchAfter?.let { sa -> searchAfter(sa) } }
                    .source { src -> src.fetch(true) }
            }, Map::class.java)

            val hits = response.hits().hits()

            for (hit in hits) {
                val doc = mutableMapOf<String, Any>()
                doc["_id"] = hit.id() ?: ""
                doc["_source"] = hit.source() ?: emptyMap<String, Any>()
                yield(doc)
            }

            searchAfter = hits.lastOrNull()?.sort()
        } while (searchAfter != null && hits.size == batchSize)
    }

    // ... other implementations following ES Java client patterns
}
```

### 4.2 LocalFileStorageRepository.kt
```kotlin
package com.cowave.search.infrastructure.storage

import com.cowave.search.config.IndexManagementConfig
import com.cowave.search.domain.index.BackupRecord
import com.cowave.search.domain.index.StorageBackend
import com.cowave.search.service.BackupStorageRepository
import com.fasterxml.jackson.databind.ObjectMapper
import org.springframework.stereotype.Repository
import java.io.File
import java.io.InputStream
import java.time.Instant
import java.util.UUID

@Repository
class LocalFileStorageRepository(
    private val config: IndexManagementConfig,
    private val objectMapper: ObjectMapper,
) : BackupStorageRepository {

    private val backupDir: File
        get() = File(config.backupPath).also { it.mkdirs() }

    private val recordsFile: File
        get() = File(backupDir, "backup_records.json")

    override fun store(
        indexName: String,
        backupId: String,
        data: InputStream,
        metadata: Map<String, Any>,
    ): String {
        val indexDir = File(backupDir, indexName).also { it.mkdirs() }
        val backupFile = File(indexDir, "$backupId.json")

        data.use { input ->
            backupFile.outputStream().use { output ->
                input.copyTo(output)
            }
        }

        return backupFile.absolutePath
    }

    override fun retrieve(storagePath: String): InputStream {
        return File(storagePath).inputStream()
    }

    override fun listBackups(indexName: String?): List<BackupRecord> {
        if (!recordsFile.exists()) return emptyList()

        val records: List<BackupRecord> = objectMapper.readValue(
            recordsFile,
            objectMapper.typeFactory.constructCollectionType(List::class.java, BackupRecord::class.java)
        )

        return if (indexName != null) {
            records.filter { it.indexName == indexName }
        } else {
            records
        }
    }

    override fun getStorageType() = StorageBackend.LOCAL_FILESYSTEM

    // ... other implementations
}
```

