package com.cowave.search.service

import com.cowave.search.controller.dto.*
import com.cowave.search.domain.index.*
import org.springframework.stereotype.Service
import java.io.*
import java.time.Instant
import java.util.UUID

@Service
class IndexManagementService(
    private val indexRepository: IndexRepository,
    private val backupStorageRepository: BackupStorageRepository,
) {
    // === Index Operations ===

    fun listIndices(pattern: String = "*"): List<IndexSummary> {
        return indexRepository.listIndices(pattern).map { indexName ->
            val metadata = indexRepository.getIndexMetadata(indexName)
            IndexSummary(
                name = indexName,
                documentCount = metadata.documentCount,
                sizeInBytes = metadata.sizeInBytes,
            )
        }
    }

    fun getIndexMetadata(indexName: String): IndexMetadata {
        return indexRepository.getIndexMetadata(indexName)
    }

    // === Settings Management ===

    fun getSettings(indexName: String): Map<String, Any> {
        return indexRepository.getSettings(indexName)
    }

    fun updateSettings(indexName: String, settings: IndexSettings): Boolean {
        return indexRepository.updateSettings(indexName, settings)
    }

    // === Mapping Management ===

    fun getMappings(indexName: String): Map<String, Any> {
        return indexRepository.getMappings(indexName)
    }

    fun updateMappings(indexName: String, mappings: Map<String, Any>): Boolean {
        return indexRepository.updateMappings(indexName, mappings)
    }

    // === Backup Operations ===

    fun createBackup(
        indexName: String,
        backupType: BackupType = BackupType.FULL,
    ): BackupRecord {
        val backupId = UUID.randomUUID().toString()
        val metadata = indexRepository.getIndexMetadata(indexName)

        // Create backup data stream
        val backupData = when (backupType) {
            BackupType.FULL -> createFullBackupStream(indexName, metadata)
            BackupType.METADATA_ONLY -> createMetadataOnlyBackupStream(metadata)
            BackupType.INCREMENTAL -> createIncrementalBackupStream(indexName)
        }

        val storagePath = backupStorageRepository.store(
            indexName = indexName,
            backupId = backupId,
            data = backupData,
            metadata = mapOf("type" to backupType.name),
        )

        val record = BackupRecord(
            id = backupId,
            indexName = indexName,
            backupType = backupType,
            storagePath = storagePath,
            storageBackend = backupStorageRepository.getStorageType(),
            documentCount = metadata.documentCount,
            sizeInBytes = metadata.sizeInBytes,
            createdAt = Instant.now(),
        )

        return backupStorageRepository.saveBackupRecord(record)
    }

    fun restoreBackup(backupId: String, targetIndexName: String? = null): RestoreResult {
        val record = backupStorageRepository.getBackupRecord(backupId)
            ?: throw IllegalArgumentException("Backup not found: $backupId")

        val targetIndex = targetIndexName ?: record.indexName
        val backupStream = backupStorageRepository.retrieve(record.storagePath)

        // Parse and restore
        return restoreFromStream(backupStream, targetIndex, record.backupType)
    }

    fun listBackups(indexName: String? = null): List<BackupRecord> {
        return backupStorageRepository.listBackups(indexName)
    }

    fun deleteBackup(backupId: String): Boolean {
        val record = backupStorageRepository.getBackupRecord(backupId)
            ?: return false
        return backupStorageRepository.delete(record.storagePath)
    }

    // === Template Management ===

    fun listTemplates(): List<IndexTemplate> {
        return indexRepository.listTemplates()
    }

    fun getTemplate(templateName: String): IndexTemplate? {
        return indexRepository.getTemplate(templateName)
    }

    fun createTemplate(template: IndexTemplate): Boolean {
        return indexRepository.createTemplate(template)
    }

    fun updateTemplate(template: IndexTemplate): Boolean {
        return indexRepository.updateTemplate(template)
    }

    fun deleteTemplate(templateName: String): Boolean {
        return indexRepository.deleteTemplate(templateName)
    }

