package com.cowave.search.controller

import com.cowave.search.controller.dto.*
import com.cowave.search.domain.index.*
import com.cowave.search.service.IndexManagementService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.*

@RestController
@RequestMapping("/api/v1/index")
class IndexController(
    private val indexManagementService: IndexManagementService,
) {
    // === Index Operations ===

    @GetMapping
    fun listIndices(
        @RequestParam(defaultValue = "*") pattern: String,
    ): List<IndexSummary> = indexManagementService.listIndices(pattern)

    @GetMapping("/{indexName}")
    fun getIndexMetadata(
        @PathVariable indexName: String,
    ): IndexMetadata = indexManagementService.getIndexMetadata(indexName)

    // === Settings Management ===

    @GetMapping("/{indexName}/settings")
    fun getSettings(
        @PathVariable indexName: String,
    ): Map<String, Any> = indexManagementService.getSettings(indexName)

    @PutMapping("/{indexName}/settings")
    fun updateSettings(
        @PathVariable indexName: String,
        @RequestBody request: UpdateSettingsRequest,
    ): Boolean = indexManagementService.updateSettings(indexName, request.toIndexSettings())

    // === Mapping Management ===

    @GetMapping("/{indexName}/mappings")
    fun getMappings(
        @PathVariable indexName: String,
    ): Map<String, Any> = indexManagementService.getMappings(indexName)

    @PutMapping("/{indexName}/mappings")
    fun updateMappings(
        @PathVariable indexName: String,
        @RequestBody request: UpdateMappingsRequest,
    ): Boolean = indexManagementService.updateMappings(indexName, request.mappings)

    // === Backup Operations ===

    @PostMapping("/{indexName}/backup")
    @ResponseStatus(HttpStatus.CREATED)
    fun createBackup(
        @PathVariable indexName: String,
        @RequestBody(required = false) request: CreateBackupRequest?,
    ): BackupRecord = indexManagementService.createBackup(
        indexName = indexName,
        backupType = request?.backupType ?: BackupType.FULL,
    )

    @GetMapping("/backups")
    fun listBackups(
        @RequestParam(required = false) indexName: String?,
    ): List<BackupRecord> = indexManagementService.listBackups(indexName)

    @GetMapping("/backups/{backupId}")
    fun getBackup(
        @PathVariable backupId: String,
    ): BackupRecord = indexManagementService.listBackups()
        .find { it.id == backupId }
        ?: throw IllegalArgumentException("Backup not found: $backupId")

    @PostMapping("/backups/{backupId}/restore")
    fun restoreBackup(
        @PathVariable backupId: String,
        @RequestBody(required = false) request: RestoreBackupRequest?,
    ): RestoreResult = indexManagementService.restoreBackup(
        backupId = backupId,
        targetIndexName = request?.targetIndexName,
    )

    @DeleteMapping("/backups/{backupId}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun deleteBackup(
        @PathVariable backupId: String,
    ) {
        indexManagementService.deleteBackup(backupId)
    }

    // === Template Management ===

    @GetMapping("/templates")
    fun listTemplates(): List<IndexTemplate> = indexManagementService.listTemplates()

    @GetMapping("/templates/{templateName}")
    fun getTemplate(
        @PathVariable templateName: String,
    ): IndexTemplate = indexManagementService.getTemplate(templateName)
        ?: throw IllegalArgumentException("Template not found: $templateName")

    @PostMapping("/templates")
    @ResponseStatus(HttpStatus.CREATED)
    fun createTemplate(
        @RequestBody request: CreateTemplateRequest,
    ): Boolean = indexManagementService.createTemplate(request.toIndexTemplate())

    @PutMapping("/templates/{templateName}")
    fun updateTemplate(
        @PathVariable templateName: String,
        @RequestBody request: UpdateTemplateRequest,
    ): Boolean = indexManagementService.updateTemplate(request.toIndexTemplate(templateName))

    @DeleteMapping("/templates/{templateName}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun deleteTemplate(
        @PathVariable templateName: String,
    ) {
        indexManagementService.deleteTemplate(templateName)
    }
}
